def has_cycle(graph: dict) -> bool:
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {}
    for start in graph:
        if color.get(start, WHITE) != WHITE:
            continue
        stack = [(start, False)]
        while stack:
            node, done = stack.pop()
            if done:
                color[node] = BLACK
                continue
            state = color.get(node, WHITE)
            if state == GRAY:
                return True
            if state == BLACK:
                continue
            color[node] = GRAY
            stack.append((node, True))
            for nxt in graph.get(node, ()):
                nstate = color.get(nxt, WHITE)
                if nstate == GRAY:
                    return True
                if nstate == WHITE:
                    stack.append((nxt, False))
    return False

